const stats = $('Get Daily Stats').first().json;
const topJobs = $('Get Top Jobs Today').all();

const topJobsText = topJobs.length > 0
  ? topJobs.map((j, i) => {
      const loc = j.json.remote ? '🌍 Remote' : j.json.location;
      return `${i+1}. *${j.json.company}* — ${j.json.title}\n   ${loc} | ${Math.round(j.json.match_score)}% match`;
    }).join('\n')
  : 'No strong matches found today.';

const aiUsage = stats.ai_calls_today || 0;
const aiLimit = stats.ai_limit || 50;
const aiBar = `${aiUsage}/${aiLimit}`;

const message = `📊 *DAILY JOB REPORT* — ${new Date().toLocaleDateString('en-GB')}

📥 Jobs discovered today: *${stats.discovered_today || 0}*
📦 Total in database: *${stats.total_jobs || 0}*

🎯 Match Results:
  ≥70% match: *${stats.matched_70 || 0}*
  ≥80% match: *${stats.matched_80 || 0}*
  ≥90% match: *${stats.matched_90 || 0}*

📝 Applications:
  Ready to submit: *${stats.apps_ready || 0}*
  Submitted: *${stats.apps_submitted || 0}*
  Interviews: *${stats.interviews || 0}*

🤖 AI Quota: ${aiBar} requests used

🏆 *Top Matches Today:*
${topJobsText}

🔗 Dashboard: http://localhost:3000`;

return [{ json: { message } }];
